  1→// @ts-nocheck
  2→// Research Appendix
  3→//
  4→// Concatenates phase2-research/*.md + phase3-disciplines/*.md into one
  5→// research-appendix.md sibling file and chunks for pagination so react-pdf
  6→// can lay it out without overflow.
  7→//
  8→// Tuning values (MAX_LINES_PER_CHUNK=230, STUB_THRESHOLD=80) were arrived at
  9→// iteratively on the Cameron Rd diligence. Do not re-tune per run; if you
 10→// find systematic issues, fix them in noetic-pdf.
 11→
 12→import * as React from '{{REACT_IMPORT}}';
 13→import * as fs from 'node:fs';
 14→import * as path from 'node:path';
 15→import {
 16→  NoeticDocument,
 17→  TitlePage,
 18→  CoverPage,
 19→  NoeticPage,
 20→  MarkdownBody,
 21→} from '{{NOETIC_PDF_INDEX}}';
 22→
 23→const md = fs.readFileSync(
 24→  path.resolve(import.meta.dirname, 'research-appendix.md'),
 25→  'utf-8',
 26→);
 27→
 28→// Strip the H1 + front-matter metadata block — already on the cover.
 29→// Body should start at the first H1 of actual content (e.g., "# Part I — ...").
 30→const body = md.replace(/^# Research Appendix[\s\S]*?(?=^# Part )/m, '');
 31→
 32→// Layout-overflow ceiling from bisection. Stay at 230 with stub-merging.
 33→const MAX_LINES_PER_CHUNK = 230;
 34→const STUB_THRESHOLD = 80;
 35→
 36→function splitByHeading(text, maxLevel) {
 37→  const headerRe =
 38→    maxLevel === 1
 39→      ? /^# (?!#)/
 40→      : maxLevel === 2
 41→        ? /^#{1,2} (?!#)/
 42→        : /^#{1,3} (?!#)/;
 43→  const lines = text.split('\n');
 44→  const chunks = [];
 45→  let current = [];
 46→  const flush = () => {
 47→    if (current.length > 0) {
 48→      chunks.push(current.join('\n').trim());
 49→      current = [];
 50→    }
 51→  };
 52→  for (const line of lines) {
 53→    if (headerRe.test(line) && current.length > 0) flush();
 54→    current.push(line);
 55→  }
 56→  flush();
 57→  return chunks.filter((c) => c.length > 0);
 58→}
 59→
 60→const lines = (s) => s.split('\n').length;
 61→
 62→function mergePass(input) {
 63→  let changed = false;
 64→  const out = [];
 65→  for (let idx = 0; idx < input.length; idx++) {
 66→    const chunk = input[idx];
 67→    if (lines(chunk) < STUB_THRESHOLD) {
 68→      if (out.length > 0 && lines(out[out.length - 1]) + lines(chunk) + 1 <= MAX_LINES_PER_CHUNK) {
 69→        out[out.length - 1] = out[out.length - 1] + '\n\n' + chunk;
 70→        changed = true;
 71→        continue;
 72→      }
 73→      const next = input[idx + 1];
 74→      if (next && lines(chunk) + lines(next) + 1 <= MAX_LINES_PER_CHUNK) {
 75→        input[idx + 1] = chunk + '\n\n' + next;
 76→        changed = true;
 77→        continue;
 78→      }
 79→    }
 80→    out.push(chunk);
 81→  }
 82→  return { out, changed };
 83→}
 84→
 85→function coalescePass(input) {
 86→  const out = [];
 87→  for (const chunk of input) {
 88→    if (out.length > 0 && lines(out[out.length - 1]) + lines(chunk) + 1 <= MAX_LINES_PER_CHUNK) {
 89→      out[out.length - 1] = out[out.length - 1] + '\n\n' + chunk;
 90→      continue;
 91→    }
 92→    out.push(chunk);
 93→  }
 94→  return out;
 95→}
 96→
 97→function chunkSections(text) {
 98→  const primary = splitByHeading(text, 1);
 99→  const atomic = [];
100→  for (const section of primary) {
101→    if (lines(section) <= MAX_LINES_PER_CHUNK) {
102→      atomic.push(section);
103→      continue;
104→    }
105→    const secondary = splitByHeading(section, 2);
106→    for (const sub of secondary) {
107→      if (lines(sub) <= MAX_LINES_PER_CHUNK) {
108→        atomic.push(sub);
109→        continue;
110→      }
111→      const tertiary = splitByHeading(sub, 3);
112→      if (tertiary.length === 1) atomic.push(sub);
113→      else atomic.push(...tertiary);
114→    }
115→  }
116→  let current = atomic;
117→  for (let pass = 0; pass < 10; pass++) {
118→    const result = mergePass([...current]);
119→    current = result.out;
120→    if (!result.changed) break;
121→  }
122→  return coalescePass(current);
123→}
124→
125→function stripBoundaryHRs(text) {
126→  let out = text.trim();
127→  while (/(\n|^)-{3,}\s*$/.test(out)) out = out.replace(/(\n|^)-{3,}\s*$/, '').trimEnd();
128→  while (/^\s*-{3,}\s*\n/.test(out)) out = out.replace(/^\s*-{3,}\s*\n/, '').trimStart();
129→  return out;
130→}
131→
132→const sections = chunkSections(body).map(stripBoundaryHRs);
133→
134→function Report() {
135→  return (
136→    <NoeticDocument title="Research Appendix — {{PROPERTY_LABEL}}">
137→      <TitlePage
138→        title="Research Appendix"
139→        subtitle="Supporting research for the {{PROPERTY_LABEL}} diligence package"
140→        date="{{REPORT_DATE}}"
141→      />
142→
143→      <CoverPage
144→        title="Research Appendix"
145→        metadata={[
146→          { label: 'Property', value: '{{PROPERTY_ADDRESS}}' },
147→          { label: 'Project', value: '{{PROJECT_DESCRIPTION}}' },
