#!/usr/bin/env tsx
import { resolve, extname } from 'node:path';
import './theme'; // Ensure fonts are registered before rendering
import { renderToFile } from './render';

async function main() {
  const [inputPath, outputPath] = process.argv.slice(2);

  if (!inputPath || !outputPath) {
    console.error('Usage: tsx render-cli.tsx <input.tsx> <output.pdf>');
    console.error('  The input file must export a default React element.');
    process.exit(1);
  }

  const absInput = resolve(inputPath);
  const absOutput = resolve(outputPath);

  if (extname(absOutput) !== '.pdf') {
    console.error('Output file must have .pdf extension');
    process.exit(1);
  }

  const mod = await import(absInput);
  const element = mod.default;

  if (!element) {
    console.error('Input file must have a default export (the React element to render).');
    process.exit(1);
  }

